<?php
/**
 * Rewrites internal links that point at a URL which 301s, so they point at the
 * destination directly.
 *
 * 794 of the site's 4,836 internal links -- 16% -- took a redirect hop. Every one
 * worked, so this is not a repair; it is removing a wasted round trip on every
 * click and every crawl, and letting the link's signal land on the page that
 * actually holds the content rather than on a redirect.
 *
 * The map is GENERATED, NOT HAND-WRITTEN. All 805 internal link targets were
 * resolved against production, the 183 that 301 had their Location header read,
 * and each destination was then re-tested to confirm it returns 200. Three
 * exclusions, each for a stated reason:
 *
 *   - '/' -> '/'    the homepage's own canonical redirect. A no-op, and
 *                   rewriting it would be meaningless.
 *   - any destination that is itself a redirect source. There were none, which
 *                   is why this pass cannot introduce a NEW hop.
 *   - any target whose destination did not return 200. There were none left
 *                   after #112 fixed the three that pointed at a 404.
 *
 * SHAPES BEING COLLAPSED. Nothing here is a typo; they are all superseded URL
 * structures the redirect layer has been faithfully absorbing:
 *
 *   98 targets  /practice-areas/{city}/{practice}/  -> /{practice}/{city-state}/
 *   40 targets  /{city}/{practice}/                 -> /{practice}/{city-state}/
 *   11 targets  /blog-{slug}/                       -> /blog/{slug}/
 *    6 targets  bare pillar roots                   -> /practice-areas/{slug}/
 *   27 targets  /contact-us/, /who-we-are/*, /es/ city pages, and slug renames
 *
 * THE SAME MATCHING RULE AS THE DEAD-LINK PASS, for the same reason: replace the
 * COMPLETE href value, never a path prefix. /charleston/ appears as a prefix of
 * /charleston/car-accident-lawyers/, and a prefix match would corrupt it.
 *
 * The six bare-pillar entries are also handled on save by inc/link-guardrails.php
 * as of #112. This clears the ones already in the database; the guard stops new
 * ones. Both are needed.
 *
 * Run:  ssh $H "wp --path=... eval-file -" < bin/fix-redirect-hops.php
 *       (append ` apply` to write; default is a dry run)
 */

$APPLY = ( isset( $args[0] ) && 'apply' === $args[0] );
$MAP   = json_decode( base64_decode( '' ), true );

if ( ! is_array( $MAP ) || ! $MAP ) { echo "MAP FAILED TO DECODE\n"; return; }

// Refuse if any destination does not resolve, or is itself in the map.
echo "--- preflight ---\n";
$bad = 0;
foreach ( $MAP as $from => $to ) {
	if ( isset( $MAP[ $to ] ) ) { echo "CHAIN: $from -> $to which also redirects\n"; $bad++; }
}
if ( $bad ) { echo "ABORTING — $bad chained destination(s)\n"; return; }
printf( "%d rewrites, no chained destinations\n\n", count( $MAP ) );

$ids = get_posts( array(
	'post_type'   => array( 'post', 'page', 'resource', 'practice_area', 'location', 'attorney', 'case_result' ),
	'post_status' => 'publish', 'numberposts' => -1, 'fields' => 'ids',
) );

$backup = array(); $counts = array(); $touched = 0;

foreach ( $ids as $id ) {
	$post = get_post( $id );
	$surfaces = array(
		'post_content'         => $post->post_content,
		'_roden_key_takeaways' => get_post_meta( $id, '_roden_key_takeaways', true ),
		'_roden_faqs'          => get_post_meta( $id, '_roden_faqs', true ),
	);

	foreach ( $surfaces as $sn => $orig ) {
		$is_array = is_array( $orig );
		$hay = $is_array ? wp_json_encode( $orig, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) : (string) $orig;
		if ( '' === $hay ) { continue; }

		$new = $hay;
		foreach ( $MAP as $from => $to ) {
			$pairs = array(
				'href="' . $from . '"'                         => 'href="' . $to . '"',
				"href='" . $from . "'"                         => "href='" . $to . "'",
				'href="https://rodenlaw.com' . $from . '"'     => 'href="https://rodenlaw.com' . $to . '"',
				'href="http://rodenlaw.com' . $from . '"'      => 'href="https://rodenlaw.com' . $to . '"',
				'href=\\"' . $from . '\\"'                     => 'href=\\"' . $to . '\\"',
				'href=\\"https://rodenlaw.com' . $from . '\\"' => 'href=\\"https://rodenlaw.com' . $to . '\\"',
			);
			foreach ( $pairs as $needle => $repl ) {
				$n = substr_count( $new, $needle );
				if ( $n ) {
					$new = str_replace( $needle, $repl, $new );
					$counts[ $from ] = ( $counts[ $from ] ?? 0 ) + $n;
				}
			}
		}

		if ( $new === $hay ) { continue; }

		$backup[] = array( 'id' => $id, 'surface' => $sn, 'before' => $hay );
		$touched++;

		if ( ! $APPLY ) { continue; }

		if ( 'post_content' === $sn ) {
			$res = wp_update_post( wp_slash( array( 'ID' => $id, 'post_content' => $new ) ), true );
			if ( is_wp_error( $res ) ) { echo "ERROR $id: " . $res->get_error_message() . "\n"; }
		} elseif ( $is_array ) {
			$dec = json_decode( $new, true );
			if ( ! is_array( $dec ) ) { echo "ERROR $id/$sn: re-decode failed, skipped\n"; continue; }
			update_post_meta( $id, $sn, $dec );
		} else {
			update_post_meta( $id, $sn, $new );
		}
	}
	unset( $post );
}

arsort( $counts );
echo ( $APPLY ? '--- applied ---' : '--- dry run ---' ) . "\n";
$i = 0;
foreach ( $counts as $from => $n ) { if ( $i++ < 12 ) { printf( "%4d  %s\n", $n, $from ); } }
printf( "  … %d more source(s)\n", max( 0, count( $counts ) - 12 ) );
echo "\nsurfaces touched: $touched   total hops removed: " . array_sum( $counts ) . "\n";

if ( ! $APPLY ) {
	echo "\n--- backup payload ---\n";
	$j = wp_json_encode( $backup, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE );
	echo ( false === $j ) ? 'ENCODE FAILED' : $j;
	echo "\n";
}
